SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, SUM(CASE WHEN status = 'FROZEN' THEN 1 ELSE 0 END) AS frozen_count, SORT_ARRAY(COLLECT_SET(status)) AS status_list, ROUND((100 * SUM(CASE WHEN account_type = 'CREDIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_credit FROM accounts WHERE YEAR(opened_date) = 2023 OR balance <= 27000 GROUP BY 1 ORDER BY opened_cohort DESC
